					function onButtonPress()
						local nPower = 0;
						local sName = "";

						if window.stpower_num then
							nPower = window.stpower_num.getValue();
						end

						if window.statustagg_string then
							sName = window.statustagg_string.getValue();
						end

						if sName == "" then
							sName = "Status/Tag";
						end

						ChatManager.SystemMessage("Status/Tag modifier added: " .. sName .. " (" .. nPower .. ")");

						if nPower ~= 0 then
							ModifierStack.addSlot(sName, nPower);
						end
					end

