buttoncontrol.script:
function getActiveActorName()
						local sIdentity = User.getCurrentIdentity();

						if sIdentity and sIdentity ~= "" then
							local nodeChar = DB.findNode("charsheet." .. sIdentity);

							if nodeChar then
								local rActor = ActorManager.resolveActor(nodeChar);

								if rActor then
									return ActorManager.getDisplayName(rActor);
								end

								return DB.getValue(nodeChar, "name", "Unknown Actor");
							end

							local sLabel = User.getIdentityLabel(sIdentity);
							if sLabel and sLabel ~= "" then
								return sLabel;
							end
						end

						if Session.IsHost then
							return "Host";
						end

						return "Unknown Actor";
					end

					function onButtonPress()
						local nPower = 0;
						local sName = "";
						local sActorName = getActiveActorName();

						if window.stpower_dd then
							nPower = tonumber(window.stpower_dd.getValue()) or 0;
						end

						if window.statustagg_string then
							sName = window.statustagg_string.getValue();
						end

						if sName == "" then
							sName = "Status/Tag";
						end

						if nPower ~= 0 then
							ModifierStack.addSlot(sName, nPower);
						end

						manager_statusmod.sendStatusTagModMessage(sName, nPower, sActorName);
					end

function getActiveActorName()
						local sIdentity = User.getCurrentIdentity();

						if sIdentity and sIdentity ~= "" then
							local nodeChar = DB.findNode("charsheet." .. sIdentity);

							if nodeChar then
								local rActor = ActorManager.resolveActor(nodeChar);

								if rActor then
									return ActorManager.getDisplayName(rActor);
								end

								return DB.getValue(nodeChar, "name", "Unknown Actor");
							end

							local sLabel = User.getIdentityLabel(sIdentity);
							if sLabel and sLabel ~= "" then
								return sLabel;
							end
						end

						if Session.IsHost then
							return "Host";
						end

						return "Unknown Actor";
					end

					function onButtonPress()
						local nPower = 0;
						local sName = "";
						local sActorName = getActiveActorName();

						if window.stpower_dd then
							nPower = (tonumber(window.stpower_dd.getValue()) or 0) * -1;
						end

						if window.statustagg_string then
							sName = window.statustagg_string.getValue();
						end

						if sName == "" then
							sName = "Status/Tag";
						end

						if nPower ~= 0 then
							ModifierStack.addSlot(sName, nPower);
						end

						manager_statusmod.sendStatusTagModMessage(sName, nPower, sActorName);
					end

function onButtonPress()
						local node = window.getDatabaseNode();

						if not node then
							window.close();
							return;
						end

						if Session.IsHost then
							node.delete();
							return;
						end

						local msgOOB = {};
						msgOOB.type = "desktoplist_deleteitem";
						msgOOB.sNode = node.getPath();

						Comm.deliverOOBMessage(msgOOB, "");
					end
